<template>
  <!-- checklist field -->
  <div
    class="field"
    v-if="
      descriptor.data_type === 'checklist' && descriptorChecklistValues.length
    "
    :key="`${descriptor.id}-checklist-wrapper`"
  >
    <label class="label" :key="`${descriptor.id}-${descriptor.name}`">
      {{ descriptor.name }}
    </label>
    <div
      class="checkbox-wrapper"
      :key="`${descriptor.id}-${i}-${option.text}-wrapper`"
      v-for="(option, i) in descriptorChecklistValues"
    >
      <input
        type="checkbox"
        @change="
          event => onMetadataCheckboxChanged(option.text, event.target.checked)
        "
        :id="`${descriptor.id}-${i}-${option.text}-checkbox`"
        :checked="metadataChecklistValues[option.text]"
        :disabled="!isEditable"
        :style="[isEditable ? { cursor: 'pointer' } : { cursor: 'auto' }]"
      />
      <label
        class="checkbox-label"
        :for="`${descriptor.id}-${i}-${option.text}-checkbox`"
        :style="[isEditable ? { cursor: 'pointer' } : { cursor: 'auto' }]"
      >
        <span>{{ option.text }}</span>
      </label>
    </div>
  </div>
  <!-- list field -->
  <combobox
    v-else-if="descriptor.data_type === 'list'"
    :label="label ?? descriptor.name"
    :options="getDescriptorChoicesOptions(descriptor)"
    :model-value="modelValue"
    @enter="onEnter"
    @update:model-value="updateValue"
  />
  <!-- boolean field -->
  <combobox-boolean
    :label="label ?? descriptor.name"
    :model-value="modelValue === 'true' ? modelValue : 'false'"
    @enter="onEnter"
    @update:model-value="updateValue"
    v-else-if="descriptor.data_type === 'boolean'"
  />
  <!-- tag list field -->
  <combobox-tag
    :label="label ?? descriptor.name"
    :options="getDescriptorChoicesOptions(descriptor, false)"
    :model-value="modelValue"
    @enter="onEnter"
    @update:model-value="updateValue"
    v-else-if="descriptor.data_type === 'taglist'"
  />
  <!-- textarea field -->
  <textarea-field
    :label="label ?? descriptor.name"
    :model-value="modelValue"
    @update:model-value="updateValue"
    v-else-if="descriptor.data_type === 'textarea'"
  />
  <!-- person field -->
  <people-field
    :label="label ?? descriptor.name"
    wide
    :people="teamPeople"
    :model-value="personMap.get(modelValue) || null"
    @update:model-value="person => updateValue(person?.id ?? '')"
    v-else-if="descriptor.data_type === 'person'"
  />
  <!-- number or text field-->
  <text-field
    :label="label ?? descriptor.name"
    :type="descriptor.data_type"
    :model-value="modelValue"
    :min="null"
    @enter="onEnter"
    @update:model-value="updateValue"
    v-else
  />
</template>

<script setup>
import { computed } from 'vue'
import { useStore } from 'vuex'

import {
  getDescriptorChecklistValues,
  getDescriptorChoicesOptions,
  getMetadataChecklistValues,
  isSupervisorInDepartments,
  parseMetadataChecklistValues
} from '@/lib/descriptors'
import { sortPeople } from '@/lib/sorting'

import Combobox from '@/components/widgets/Combobox.vue'
import ComboboxBoolean from '@/components/widgets/ComboboxBoolean.vue'
import ComboboxTag from '@/components/widgets/ComboboxTag.vue'
import PeopleField from '@/components/widgets/PeopleField.vue'
import TextField from '@/components/widgets/TextField.vue'
import TextareaField from '@/components/widgets/TextareaField.vue'

const store = useStore()
const isCurrentUserAdmin = computed(() => store.getters.isCurrentUserAdmin)
const isCurrentUserManager = computed(() => store.getters.isCurrentUserManager)
const isCurrentUserSupervisor = computed(
  () => store.getters.isCurrentUserSupervisor
)
const user = computed(() => store.getters.user)
const currentProduction = computed(() => store.getters.currentProduction)
const personMap = computed(() => store.getters.personMap)

const teamPeople = computed(() =>
  sortPeople(
    (currentProduction.value?.team || [])
      .map(personId => personMap.value.get(personId))
      .filter(Boolean)
  )
)

const props = defineProps({
  descriptor: {
    type: Object,
    required: true
  },
  entity: {
    type: Object,
    required: true
  },
  label: {
    type: String
  },
  modelValue: {
    type: [Number, String, Object],
    default: ''
  }
})

const emit = defineEmits(['enter', 'update:model-value'])

const descriptorChecklistValues = computed(() => {
  return getDescriptorChecklistValues(props.descriptor)
})

// The form value holds the ticks not saved yet: the stored entity only
// seeds a form without a value for this field.
const metadataChecklistValues = computed(() =>
  props.modelValue
    ? parseMetadataChecklistValues(props.descriptor, props.modelValue)
    : getMetadataChecklistValues(props.descriptor, props.entity)
)

// Resolved against the edited entity's own production when it carries
// project context (Edit*Modal.vue). BuildFilterModal.vue passes entity={}
// (used from both production-scoped and cross-production ActionPanel
// pages), so it falls back to the global role there, matching current
// behavior.
const entityProductionId = computed(() => props.entity?.project_id)
const isEntityManager = computed(
  () =>
    isCurrentUserAdmin.value ||
    (entityProductionId.value
      ? store.getters.currentUserRoleForProduction(entityProductionId.value) ===
        'manager'
      : isCurrentUserManager.value)
)
const isEntitySupervisor = computed(() =>
  entityProductionId.value
    ? store.getters.currentUserRoleForProduction(entityProductionId.value) ===
      'supervisor'
    : isCurrentUserSupervisor.value
)

const isEditable = computed(() => {
  return Boolean(
    isEntityManager.value ||
    isSupervisorInDepartments(
      user.value,
      isEntitySupervisor.value,
      props.descriptor.departments
    )
  )
})

const updateValue = value => {
  emit('update:model-value', value)
}

const onEnter = () => {
  emit('enter')
}

const onMetadataCheckboxChanged = (option, value) => {
  updateValue(
    JSON.stringify({ ...metadataChecklistValues.value, [option]: value })
  )
}
</script>

<style lang="scss" scoped>
.checkbox-wrapper {
  display: flex;
  align-items: center;
  white-space: nowrap;
}

.checkbox-label {
  display: inline-flex;
  position: relative;
  padding-left: 0.5rem;
  padding-right: 0.5rem;
  white-space: normal;
  cursor: pointer;
}
</style>
